package dev.spike.glucobridge.libreview

import dev.spike.glucobridge.treatments.Treatment
import dev.spike.glucobridge.treatments.TreatmentJson
import java.io.File
import java.time.ZoneId
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.long
import org.junit.Assert.assertEquals
import org.junit.Test

class LibreViewPayloadTest {
    /** spikes/libreview/fixture.json, generated by lv.py — the Mac app checks the same file. */
    private val fixture = Json.parseToJsonElement(File("../../libreview/fixture.json").readText()).jsonObject

    @Test fun payloadMatchesFixtureByteForByte() {
        val trs = TreatmentJson.decodeFromString<List<Treatment>>(fixture["treatments"].toString())
        val got = LibreViewPayload.payload(trs, fixture.str("deviceId"), fixture.str("token"),
            fixture["now"]!!.jsonPrimitive.long, ZoneId.of(fixture.str("zone")))
        assertEquals(fixture.str("expectedPayload"), got)
    }

    @Test fun recordNumbersMatchFixture() {
        val trs = TreatmentJson.decodeFromString<List<Treatment>>(fixture["treatments"].toString()).associateBy { it.id }
        for (row in fixture["recordNumbers"]!!.jsonArray) {
            val (id, version, rn) = row.jsonArray.map { it.jsonPrimitive.content }
            assertEquals("$id@$version", rn.toLong(), LibreViewPayload.recordNumber(trs.getValue(id), version.toLong()))
        }
    }

    /** Expected values computed by Juggluco's own C++ (`libreviewHistorAlg(serial, 0, 19)`). */
    @Test fun historMatchesJuggluco() {
        assertEquals(169657575276544000L, LibreViewPayload.histor("09ECXALLU"))
        assertEquals(324682999993466880L, LibreViewPayload.histor("0K0R2XYZ7"))
        assertEquals(-524288L, LibreViewPayload.histor("ZZZZZZZZZ"))         // wraps like int64 in C
        assertEquals(LibreViewPayload.histor("09ECXALLU"), LibreViewPayload.histor("XX09ECXALLU")) // last 9 chars
    }

    @Test fun mergeIsLastWriterWinsAndKeepsUploadWatermark() {
        val a = Treatment(id = "x", k = "rapid", a = 1.0, t = 0, u = 10, o = "phone", lv = 10)
        val b = a.copy(a = 2.0, u = 11, o = "mac", lv = 0)
        assertEquals(b.copy(lv = 10), Treatment.merge(a, b))
        assertEquals(b.copy(lv = 10), Treatment.merge(b, a.copy(lv = 10)))  // older loses, watermark kept
        val tie = a.copy(a = 3.0, o = "mac", lv = 0)
        assertEquals(a, Treatment.merge(a, tie))                           // same u: "phone" > "mac", either order
        assertEquals(a, Treatment.merge(tie, a))
    }

    private fun JsonObject.str(k: String) = this[k]!!.jsonPrimitive.content
}
